  const agentIcon=name=>`<svg class="icon" aria-hidden="true"><use href="#ico-${name}"/></svg>`;
  const agentMark='<span class="ws-agent-mark" aria-hidden="true"><svg class="icon"><use href="#ico-spark"/></svg></span>';
  const agentButton=()=>button('agent',agentMark+'<span>Ask Agent</span>','pa-ask-agent');
  const personal=()=>document.body.dataset.wsType!=='team';
  const seeds=todayAssetRecords.filter(r=>['todo','schedule'].includes(r.type)).map(r=>({...r,start:(r.eventDate||r.dueDate)+'T'+r.time,end:r.end?(r.eventDate+'T'+r.end):'',source:'capture',notes:'',reminder:r.type==='schedule'?'15':'none',location:r.type==='schedule'?(r.id==='schedule-1'?'线上会议':'会议室 A'):'',participants:r.type==='schedule'?(r.id==='schedule-1'?'Kevin、张伟':'Alice、张伟'):'',links:[],capture:r.detail,created:(r.createdDate||r.eventDate||r.dueDate)+'T09:19:00+08:00',updated:'seed'}));
  for(const file of thoughtArchiveData.todo.files)for(const [i,r] of file.entries.entries())if(!r.assetId){const id=`archive-todo-${file.month}-${i}`;seeds.push({...r,id,type:'todo',start:r.date+'T'+r.time,end:'',source:'capture',reminder:'none',notes:'',location:'',participants:'',links:[],done:r.detail.includes('已完成'),capture:r.detail,created:r.date+'T'+r.time+':00+08:00',updated:'seed'});}
  const firstMeeting=window.MeetingDetail?.snapshot()?.[0];if(firstMeeting)seeds.filter(r=>r.type==='schedule').forEach(r=>r.links=[firstMeeting.id]);
  let repo;try{repo=M.create(localStorage,seeds);}catch(e){showToast(e.message);return;}
  const demoDay=M.today();
  try{repo.seedCalendar([
    ['calendar-meeting-review','schedule','交付方案讨论','09:30','10:30',0,'确认本周产品范围与评审结论。','Kevin、张伟'],
    ['calendar-meeting-investor','schedule','客户试点沟通','14:00','15:00',0,'讨论试点验收与交付安排。','林晓、张伟'],
    ['calendar-meeting-weekly','schedule','产品周会','16:30','17:30',1,'整理讨论中的决定与后续安排。','产品团队'],
    ['calendar-todo-demo','todo','准备客户 Demo 环境','09:30','',0,'核对录音同步与会议详情演示。',''],
    ['calendar-todo-feedback','todo','汇总客户价格反馈','18:00','',0,'归纳三次客户沟通中的价格关注点。',''],
    ['calendar-todo-delivery','todo','更新试点交付说明','15:00','',2,'补齐异常处理流程与验收口径。','']
  ].map(([id,type,title,time,end,offset,notes,participants])=>({id,type,title,start:M.shiftDay(demoDay,offset)+'T'+time,end:end?M.shiftDay(demoDay,offset)+'T'+end:'',notes,participants,source:'capture',capture:notes,location:type==='schedule'?'线上会议':'',reminder:'15',links:[],done:false,created:demoDay+'T09:00:00+08:00',updated:'seed'})));}catch(e){showToast(e.message);}
  let calendarDate=M.today(),calendarMode='day';
  let agentOptions={ids:[],mode:'quick',web:false};
  let archiveReturn=null;
  let selected=null,editing=false,draft=null,draftBaseline='',listType='todo',agentDraft=null,sessionId=null,recordingAsset=null;
  const root=document.createElement('section');root.id='personal-actions';root.className='main-inner pa-workspace';root.dataset.mainView='personal-actions';root.hidden=true;root.innerHTML='<div class="pa-content"></div>';$('.main').append(root);const content=$('.pa-content',root);
  const nav=document.createElement('button');nav.type='button';nav.id='todos-entry';nav.className='nav-item';nav.dataset.pa='todos';nav.innerHTML='<span class="nav-left"><span class="nav-icon"><svg class="icon" viewBox="0 0 24 24"><path d="m3 5 2 2 3-4M11 5h10M3 12l2 2 3-4M11 12h10M3 19l2 2 3-4M11 19h10"/></svg></span><span class="nav-label">日程与待办</span></span>';
  const contact=$('[data-contacts-entry]');(contact.closest('.knowledge-tree-leaf-row')||contact).before(nav);

  const archiveWrap=document.createElement('div');archiveWrap.className='pa-archive-wrap';$('#recording-card').before(archiveWrap);archiveWrap.append($('#recording-card'));
  const rail=document.createElement('aside');rail.id='pa-agent';rail.className='pa-agent';rail.hidden=true;rail.setAttribute('aria-label','闪念 Ask Agent');
  const dialog=document.createElement('dialog');dialog.className='pa-dialog';dialog.setAttribute('aria-label','编辑个人记录');document.body.append(dialog);let dialogAction=null,dialogCancel=null,dialogReturn=null;
  const createDialog=document.createElement('dialog');createDialog.className='pa-create-dialog';createDialog.setAttribute('aria-label','新建日程或待办');document.body.append(createDialog);
  const closeCreate=()=>{editing=false;createDialog.close();createDialog.innerHTML='';};
  const cancelCreate=()=>{if(guard(closeCreate))return;closeCreate();};
  createDialog.addEventListener('cancel',e=>{e.preventDefault();cancelCreate();});
  const source=r=>M.sources[r.source]||'闪念提取';
  const record=id=>repo.snapshot().records.find(r=>r.id===id);
  const meetings=()=>window.MeetingDetail.snapshot();
  const date=v=>{const value=String(v||'');if(/(?:Z|[+-]\d{2}:\d{2})$/.test(value)&&Number.isFinite(Date.parse(value)))return new Date(Date.parse(value)+8*3600000).toISOString().replace('T',' ').slice(0,16);return value.replace('T',' ').slice(0,16);};
  const field=(label,name,value='',type='text',extra='')=>`<label class="pa-field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`;
  const reminderSelect=r=>`<label class="pa-field">提醒时间<select name="reminder">${M.reminders.map(([v,t])=>`<option value="${v}" ${v===r.reminder?'selected':''}>${t}</option>`).join('')}</select></label>`;
  function formFields(r){return `${field('标题','title',r.title,'text','required maxlength="200" placeholder="为这次安排起个名字"')}<div class="pa-form-grid">${field(r.type==='schedule'?'开始时间':'截止时间','start',r.start,'datetime-local','required')}${r.type==='schedule'?field('结束时间','end',r.end,'datetime-local','required'):''}${reminderSelect(r)}<p class="pa-hint">时间统一按 GMT+8（北京时间）</p></div>${r.type==='schedule'?`<div class="pa-form-grid">${field('地点','location',r.location,'text','maxlength="300" placeholder="线上链接或会议地点"')}${field('参与人','participants',r.participants,'text','maxlength="300" placeholder="用顿号分隔姓名"')}</div>`:''}<label class="pa-field">我的备注<textarea name="notes" maxlength="2000" rows="4" placeholder="补充需要记住的内容">${esc(r.notes)}</textarea><small>最多 2000 字</small></label>`;}
  function values(form,base){return {...base,...Object.fromEntries(new FormData(form))};}
